mapper.select:
SELECT COUNT(*) 
FROM RESERVATION r
INNER JOIN ASSET a ON r.ASSET_ID = a.ASSET_ID
WHERE a.NAME = #{name}
AND a.CATEGORY = #{category}
AND a.COMPANY = #{company}
AND a.IS_DELETED = 'N'
AND r.STATUS IN ('PENDING', 'APPROVED', 'ACTIVE')
AND (
    (r.START_TIME <= #{startAt} AND r.END_TIME > #{startAt}) OR
    (r.START_TIME < #{endAt} AND r.END_TIME >= #{endAt}) OR
    (r.START_TIME >= #{startAt} AND r.END_TIME <= #{endAt})
)

SELECT r.START_TIME, r.END_TIME
FROM RESERVATION r
INNER JOIN ASSET a ON r.ASSET_ID = a.ASSET_ID
WHERE a.NAME = #{name}
AND a.CATEGORY = #{category}
AND a.COMPANY = #{company}
AND a.IS_DELETED = 'N'
AND r.STATUS IN ('PENDING', 'APPROVED', 'ACTIVE')
AND r.END_TIME >= #{from}
AND r.START_TIME <= #{to}
ORDER BY r.START_TIME
